"""Unit tests for examples/_aer_numeric_check.py (the NUMERIC-CHECK protocol)."""

from __future__ import annotations

import pytest

from _aer_numeric_check import PROTOCOL_PREFIX, numeric_check


class TestTargetTolerance:
    def test_within_tolerance_passes_and_returns_float(self):
        result = numeric_check("beta", 0.02, target=0.0, tol=0.03)
        assert result == pytest.approx(0.02)
        assert isinstance(result, float)

    def test_exact_boundary_passes(self):
        # abs(got - target) == tol is accepted (tolerance is inclusive).
        assert numeric_check("edge", 1.1, target=1.0, tol=0.1) == pytest.approx(1.1)

    def test_outside_tolerance_raises_assertion_error(self):
        with pytest.raises(AssertionError, match="numeric check failed"):
            numeric_check("beta", 0.5, target=0.0, tol=0.01)

    def test_negative_deviation_within_tolerance_passes(self):
        assert numeric_check("neg", -0.02, target=0.0, tol=0.03) == pytest.approx(-0.02)

    def test_target_without_tol_raises_value_error(self):
        with pytest.raises(ValueError, match="'target' requires 'tol'"):
            numeric_check("bad-spec", 1.0, target=1.0)


class TestBounds:
    def test_lo_bound_at_boundary_passes(self):
        assert numeric_check("coverage", 0.94, lo=0.94) == pytest.approx(0.94)

    def test_lo_bound_below_raises(self):
        with pytest.raises(AssertionError):
            numeric_check("coverage", 0.93, lo=0.94)

    def test_hi_bound_at_boundary_passes(self):
        assert numeric_check("rate", 1.0, hi=1.0) == pytest.approx(1.0)

    def test_hi_bound_above_raises(self):
        with pytest.raises(AssertionError):
            numeric_check("rate", 1.01, hi=1.0)

    def test_lo_hi_band_pass(self):
        assert numeric_check("band", 0.5, lo=0.1, hi=1.0) == pytest.approx(0.5)

    def test_lo_hi_band_fails_below(self):
        with pytest.raises(AssertionError):
            numeric_check("band", 0.05, lo=0.1, hi=1.0)

    def test_lo_hi_band_fails_above(self):
        with pytest.raises(AssertionError):
            numeric_check("band", 1.5, lo=0.1, hi=1.0)

    def test_no_spec_at_all_raises_value_error(self):
        with pytest.raises(ValueError, match="pass either target"):
            numeric_check("no-spec", 1.0)


class TestProtocolLine:
    def test_pass_line_format_target_tol(self, capsys):
        numeric_check("my check", 1.2345678, target=1.23, tol=0.01)
        out = capsys.readouterr().out
        assert out == "NUMERIC-CHECK | my check | got=1.2346 | target=1.23 tol=0.01 | PASS\n"

    def test_pass_line_format_lo_hi(self, capsys):
        numeric_check("rate", 0.5, lo=0.1, hi=1.0)
        out = capsys.readouterr().out
        assert out == "NUMERIC-CHECK | rate | got=0.5000 | >=0.1 <=1 | PASS\n"

    def test_lo_only_spec(self, capsys):
        numeric_check("cov", 0.95, lo=0.94)
        assert "| >=0.94 | PASS" in capsys.readouterr().out

    def test_fail_line_is_printed_before_the_raise(self, capsys):
        with pytest.raises(AssertionError):
            numeric_check("drifted", 9.0, target=0.0, tol=0.1)
        out = capsys.readouterr().out
        assert out.startswith(PROTOCOL_PREFIX + " | drifted | got=9.0000 |")
        assert out.rstrip().endswith("FAIL")

    def test_prefix_constant_matches_smoke_runner_contract(self):
        # scripts/run_example_smoke.py greps for this exact prefix.
        assert PROTOCOL_PREFIX == "NUMERIC-CHECK"

    def test_numeric_string_input_is_coerced(self, capsys):
        assert numeric_check("coerced", "0.5", lo=0.0) == pytest.approx(0.5)
        assert "got=0.5000" in capsys.readouterr().out

"""Unit tests for scripts/run_example_smoke.py helper functions."""

from __future__ import annotations

import sys
from pathlib import Path

import pytest

import run_example_smoke as smoke
import validate_repo


class TestNumericChecksIn:
    def test_counts_pass_and_fail_lines(self):
        output = "\n".join(
            [
                "some setup text",
                "NUMERIC-CHECK | a | got=1.0000 | target=1 tol=0.1 | PASS",
                "NUMERIC-CHECK | b | got=9.0000 | target=1 tol=0.1 | FAIL",
                "NUMERIC-CHECK | c | got=0.9500 | >=0.94 | PASS",
                "trailing text",
            ]
        )
        assert smoke.numeric_checks_in(output) == (3, 1)

    def test_empty_output_counts_zero(self):
        assert smoke.numeric_checks_in("") == (0, 0)

    def test_non_protocol_lines_are_ignored(self):
        output = "\n".join(
            [
                "  NUMERIC-CHECK | indented is not protocol | PASS",
                "NUMERIC-CHECKX| wrong prefix | PASS",
                "the word FAIL alone does not count",
            ]
        )
        assert smoke.numeric_checks_in(output) == (0, 0)

    def test_trailing_whitespace_on_fail_line_still_counts_failed(self):
        output = "NUMERIC-CHECK | x | got=2.0000 | <=1 | FAIL   "
        assert smoke.numeric_checks_in(output) == (1, 1)

    def test_pass_line_is_not_counted_as_failed(self):
        output = "NUMERIC-CHECK | x | got=0.5000 | <=1 | PASS"
        assert smoke.numeric_checks_in(output) == (1, 0)


class TestTextTail:
    def test_short_text_returned_whole(self):
        assert smoke.text_tail("a\nb\nc") == "a\nb\nc"

    def test_long_text_truncated_with_ellipsis_marker(self):
        text = "\n".join(str(i) for i in range(40))
        tail = smoke.text_tail(text, lines=30)
        lines = tail.splitlines()
        assert lines[0] == "..."
        assert lines[1:] == [str(i) for i in range(10, 40)]

    def test_custom_line_budget(self):
        assert smoke.text_tail("a\nb\nc", lines=2) == "...\nb\nc"

    def test_surrounding_whitespace_is_stripped(self):
        assert smoke.text_tail("\n\na\nb\n\n") == "a\nb"


class TestPackageImportNames:
    def test_mapped_package_returns_import_name(self):
        assert smoke.package_import_names("python-dateutil") == ["dateutil"]

    def test_identity_mapping(self):
        assert smoke.package_import_names("numpy") == ["numpy"]

    def test_unmapped_package_falls_back_to_underscored_name(self):
        assert smoke.package_import_names("some-unmapped-pkg") == ["some_unmapped_pkg"]

    def test_every_mapped_name_is_returned_sorted(self):
        for package in set(validate_repo.PYTHON_IMPORT_PACKAGE_MAP.values()):
            names = smoke.package_import_names(package)
            assert names == sorted(names)
            assert names


class TestRVector:
    def test_sorted_quoted_vector(self):
        assert smoke.r_vector({"fixest", "did"}) == 'c("did", "fixest")'

    def test_single_package(self):
        assert smoke.r_vector({"did"}) == 'c("did")'

    def test_empty_set(self):
        assert smoke.r_vector(set()) == "c()"


class TestCommandFor:
    def test_python_script_uses_current_interpreter(self):
        command = smoke.command_for(Path("/somewhere/demo.py"))
        assert command == [sys.executable, "demo.py"]

    def test_r_script_uses_rscript(self):
        command = smoke.command_for(Path("/somewhere/demo.R"))
        assert Path(command[0]).name == "Rscript"
        assert command[1] == "demo.R"

    def test_unsupported_suffix_raises(self):
        with pytest.raises(ValueError, match="unsupported script suffix"):
            smoke.command_for(Path("/somewhere/demo.do"))


class TestIterDemoScripts:
    def test_python_filter_yields_only_python_scripts(self):
        scripts = list(smoke.iter_demo_scripts(None, "python"))
        assert scripts
        assert all(path.suffix == ".py" for _, path in scripts)

    def test_r_filter_yields_only_r_scripts(self):
        scripts = list(smoke.iter_demo_scripts(None, "r"))
        assert scripts
        assert all(path.suffix == ".R" for _, path in scripts)

    def test_selected_demo_restricts_output(self):
        scripts = list(smoke.iter_demo_scripts({"shift-share-demo"}, "all"))
        assert scripts
        assert {demo for demo, _ in scripts} == {"shift-share-demo"}

    def test_all_yielded_scripts_exist_on_disk(self):
        for _, path in smoke.iter_demo_scripts(None, "all"):
            assert path.is_file(), path

"""Unit tests for scripts/skill_audit.py scorers plus repo-level gate invariants."""

from __future__ import annotations

import skill_audit as sa
import validate_repo as vr


class TestEstimateTokens:
    def test_four_chars_per_token(self):
        assert sa.estimate_tokens("x" * 400) == 100

    def test_rounds_up(self):
        assert sa.estimate_tokens("abc") == 1
        assert sa.estimate_tokens("abcde") == 2

    def test_monotonic(self):
        assert sa.estimate_tokens("x" * 400) > sa.estimate_tokens("x" * 40)


class TestScoreBudget:
    def test_in_band_scores_full(self):
        assert sa.score_budget(sa.TOKEN_BUDGET_LOW) == 1.0
        assert sa.score_budget(1500) == 1.0
        assert sa.score_budget(sa.TOKEN_BUDGET_HIGH) == 1.0

    def test_thin_document_penalized_proportionally(self):
        assert sa.score_budget(150) == 0.5

    def test_over_budget_decays_to_zero(self):
        assert sa.score_budget(sa.TOKEN_BUDGET_HIGH + sa.TOKEN_OVER_SLACK) == 0.0
        # One tenth of the slack over budget costs one tenth of the score.
        assert sa.score_budget(sa.TOKEN_BUDGET_HIGH + sa.TOKEN_OVER_SLACK // 10) == 0.9


class TestScoreTrigger:
    def test_full_score_description(self):
        score, issues = sa.score_trigger("Use when drafting after the data exist, before submission.")
        assert score == 1.0
        assert issues == []

    def test_missing_use_when_flagged(self):
        score, issues = sa.score_trigger("Draft the results once the tables exist.")
        assert score < 1.0
        assert "no-use-when" in issues

    def test_empty_description(self):
        assert sa.score_trigger("") == (0.0, ["no-description"])

    def test_over_long_description_flagged(self):
        _, issues = sa.score_trigger("Use when " + "x " * 250)
        assert "too-long" in issues

    def test_too_short_description_flagged(self):
        _, issues = sa.score_trigger("Use when short.")
        assert "too-short" in issues


class TestScoreStructure:
    def test_all_house_sections_present(self):
        score, missing = sa.score_structure(list(sa.HOUSE_SECTIONS))
        assert score == 1.0
        assert missing == []

    def test_missing_sections_reported(self):
        score, missing = sa.score_structure(["Overview"])
        assert score == 0.25
        assert set(missing) == {"When to Use", "Handoff", "Anti-Patterns"}

    def test_match_is_case_insensitive_substring(self):
        score, _ = sa.score_structure(["1. overview of the task"])
        assert score == 0.25


class TestScoreDirective:
    def test_bullets_beat_prose(self):
        bullets = "\n".join(f"- step {i}" for i in range(10))
        prose = "\n".join("This sentence explains a concept at length." for _ in range(10))
        assert sa.score_directive(bullets)[0] > sa.score_directive(prose)[0]

    def test_empty_body_scores_zero(self):
        assert sa.score_directive("") == (0.0, 0, 0)

    def test_directive_verb_line_counts(self):
        assert sa.is_directive_line("Report the exact sample size.")
        assert sa.is_directive_line("- any list item")
        assert sa.is_directive_line("| any | table | row |")
        assert not sa.is_directive_line("The model is a linear specification.")


class TestScoreHygiene:
    def test_filler_scores_hits(self):
        _, hits = sa.score_hygiene("The model delve into the data and plays a crucial role here.\n", 12)
        assert hits

    def test_quoted_filler_is_skipped(self):
        _, hits = sa.score_hygiene('Avoid writing "this plays a crucial role" in the body.\n', 12)
        assert not hits

    def test_anti_pattern_section_is_negation_context(self):
        body = "## Anti-Patterns\n- delve into the literature without naming papers\n"
        _, hits = sa.score_hygiene(body, 12)
        assert not hits

    def test_econometric_leverage_not_flagged(self):
        _, hits = sa.score_hygiene("Report leverage and Cook's distance.\n", 8)
        assert not hits

    def test_leverage_as_verb_is_flagged(self):
        _, hits = sa.score_hygiene("We leverage the panel structure here.\n", 8)
        assert "leverage (verb)" in hits

    def test_clean_body_scores_full(self):
        score, hits = sa.score_hygiene("Report the point estimate and its cluster-robust SE.\n", 10)
        assert score == 1.0
        assert hits == []


class TestScoreHandoff:
    def test_section_and_routing_score_full(self):
        assert sa.score_handoff(["Handoff"], "NEXT SKILL: aer-submission") == 1.0

    def test_section_only(self):
        assert sa.score_handoff(["Handoff"], "no routing text") == 0.6

    def test_routing_only(self):
        assert sa.score_handoff(["Overview"], "NEXT STEP: draft tables") == 0.4

    def test_arrow_counts_as_routing(self):
        assert sa.score_handoff(["Overview"], "results → tables") == 0.4

    def test_absent_everywhere(self):
        assert sa.score_handoff(["Overview"], "no routing here") == 0.0


class TestScoreSubstance:
    RICH = (
        'The reform raises earnings by 4.2 percent (p = 0.01) over 48,212 firms.\n'
        '> "The point estimate implies a $4.5 billion gain," the authors write.\n'
        '```latex\nY = \\beta D\n```\n'
        'Here $\\beta$ is the object of interest.\n'
    )

    def test_rich_body_clears_floor(self):
        assert sa.score_substance(self.RICH)["anchors"] >= sa.SUBSTANCE_FLOOR

    def test_thin_body_trips_floor(self):
        thin = "Draft the section. Keep it tight. Route onward when done.\n"
        assert sa.score_substance(thin)["anchors"] < sa.SUBSTANCE_FLOOR

    def test_figures_counted(self):
        assert sa.score_substance("4.2 percent and 0.042 and 48,212")["figures"] >= 3

    def test_short_quotes_are_not_exemplars(self):
        assert sa.score_substance('say "no" here')["exemplars"] == 0

    def test_long_quote_is_an_exemplar(self):
        body = '"identification comes from within-state variation over time" is quoted.\n'
        assert sa.score_substance(body)["exemplars"] == 1

    def test_blockquote_counts_once_per_block(self):
        body = "> quoted line one\n> quoted line two\nplain\n> second block\n"
        assert sa.score_substance(body)["exemplars"] == 2

    def test_anchor_total_is_sum_of_parts(self):
        substance = sa.score_substance(self.RICH)
        assert substance["anchors"] == (
            substance["figures"] + substance["exemplars"] + substance["blocks"]
        )


class TestGrade:
    def test_cutoffs(self):
        assert sa.grade(95) == "A"
        assert sa.grade(90) == "A"
        assert sa.grade(89.9) == "B"
        assert sa.grade(75) == "C"
        assert sa.grade(60) == "D"
        assert sa.grade(59.9) == "F"


class TestSplitFrontmatter:
    def test_fields_and_body_separated(self):
        text = "---\nname: aer-demo\ndescription: Use when testing.\n---\n# Body\n"
        fields, body = sa.split_frontmatter(text)
        assert fields == {"name": "aer-demo", "description": "Use when testing."}
        assert body == "# Body\n"

    def test_no_frontmatter_returns_whole_text(self):
        fields, body = sa.split_frontmatter("# Just a body\n")
        assert fields == {}
        assert body == "# Just a body\n"


class TestAuditSkill:
    def test_synthetic_skill_audit_shape(self, tmp_path):
        skill_dir = tmp_path / "aer-synthetic"
        skill_dir.mkdir()
        skill_md = skill_dir / "SKILL.md"
        skill_md.write_text(
            "---\n"
            "name: aer-synthetic\n"
            "description: Use when testing the auditor after fixtures exist.\n"
            "---\n"
            "## Overview\n"
            "- Report the effect as 4.2 percent (p = 0.01) over 48,212 firms.\n"
            "## When to Use\n"
            "- Use after the estimates exist.\n"
            "## Handoff\n"
            "NEXT SKILL: aer-submission\n"
            "## Anti-Patterns\n"
            "- Never round p-values to zero.\n",
            encoding="utf-8",
        )
        result = sa.audit_skill(skill_md)
        assert result["name"] == "aer-synthetic"
        assert set(result["dimensions"]) == set(sa.WEIGHTS)
        assert 0 <= result["score"] <= 100
        assert result["grade"] in "ABCDF"
        assert result["dimensions"]["structure"] == 1.0
        assert result["dimensions"]["handoff"] == 1.0
        assert result["substance"]["anchors"] > 0

    def test_recommendations_flag_thin_substance(self, tmp_path):
        skill_dir = tmp_path / "aer-thin"
        skill_dir.mkdir()
        skill_md = skill_dir / "SKILL.md"
        skill_md.write_text(
            "---\nname: aer-thin\ndescription: Use when testing.\n---\n## Overview\nShort.\n",
            encoding="utf-8",
        )
        result = sa.audit_skill(skill_md)
        assert result["substance"]["anchors"] < sa.SUBSTANCE_FLOOR
        assert any("THIN" in tip for tip in result["recommendations"])


class TestRepoGateInvariants:
    """The shipped skills must clear the Makefile audit-skills-gate thresholds."""

    SCORE_GATE = 85
    SUBSTANCE_GATE = 8

    def test_makefile_gate_matches_asserted_thresholds(self, repo_root):
        body = vr.make_target_body((repo_root / "Makefile").read_text(encoding="utf-8"), "audit-skills-gate")
        assert f"--gate {self.SCORE_GATE} --substance-gate {self.SUBSTANCE_GATE}" in body

    def test_every_skill_clears_the_score_gate(self):
        results = sa.collect(None)
        assert results, "no skills audited"
        failing = [(r["name"], r["score"]) for r in results if r["score"] < self.SCORE_GATE]
        assert failing == []

    def test_every_skill_clears_the_substance_gate(self):
        results = sa.collect(None)
        thin = [
            (r["name"], r["substance"]["anchors"])
            for r in results
            if r["substance"]["anchors"] < self.SUBSTANCE_GATE
        ]
        assert thin == []

    def test_dimension_weights_sum_to_100(self):
        assert sum(sa.WEIGHTS.values()) == 100

"""Unit tests for scripts/validate_repo.py pure helpers and registries."""

from __future__ import annotations

import re

import validate_repo as vr


# Assembled at runtime so this test file does not itself trip the repository's
# unfinished-work marker scan.
_TODO_MARKER = "TO" + "DO"


class TestRel:
    def test_rel_returns_posix_relative_path(self):
        assert vr.rel(vr.ROOT / "scripts" / "validate_repo.py") == "scripts/validate_repo.py"

    def test_rel_nested_path(self):
        path = vr.ROOT / "examples" / "shift-share-demo" / "README.md"
        assert vr.rel(path) == "examples/shift-share-demo/README.md"


class TestDeclaredDeps:
    def test_python_comment_style(self, tmp_path):
        script = tmp_path / "demo.py"
        script.write_text("# Deps: numpy, pandas\nimport numpy\n", encoding="utf-8")
        assert vr.declared_deps(script) == ["numpy", "pandas"]

    def test_docstring_style(self, tmp_path):
        script = tmp_path / "demo.py"
        script.write_text('"""Demo.\nDeps: numpy, scipy\n"""\n', encoding="utf-8")
        assert vr.declared_deps(script) == ["numpy", "scipy"]

    def test_parenthetical_note_is_stripped(self, tmp_path):
        script = tmp_path / "demo.py"
        script.write_text("# Deps: numpy, rdrobust (optional extras)\n", encoding="utf-8")
        assert vr.declared_deps(script) == ["numpy", "rdrobust"]

    def test_names_are_lowercased(self, tmp_path):
        script = tmp_path / "demo.R"
        script.write_text("# Deps: Fixest, DID\n", encoding="utf-8")
        assert vr.declared_deps(script) == ["fixest", "did"]

    def test_no_declaration_returns_empty(self, tmp_path):
        script = tmp_path / "demo.py"
        script.write_text("import numpy\n", encoding="utf-8")
        assert vr.declared_deps(script) == []

    def test_only_first_declaration_wins(self, tmp_path):
        script = tmp_path / "demo.py"
        script.write_text("# Deps: numpy\n# Deps: pandas\n", encoding="utf-8")
        assert vr.declared_deps(script) == ["numpy"]


class TestHeadingSlugsAndTargets:
