class TestMakeTargetBody:
    FIXTURE = "\n".join(
        [
            ".PHONY: first second",
            "",
            "first:",
            "\tpython3 scripts/validate_repo.py",
            "\tgit diff --check",
            "",
            "second:",
            "\tgit diff --cached --check",
